import { CaptchaTaskComponent } from "@hunt/puzzle-components";
import { createRoot } from "react-dom/client";
import { CAPTCHA_ELEMENTS } from "./data";

const captcha_elem = document.getElementById("campus-visit-root");
if (captcha_elem) {
  const root = createRoot(captcha_elem);
  root.render(
    <CaptchaTaskComponent
      taskSlug="campus_visit"
      flavorText="Help the Kitty City Puzzmon pick prime locations to visit on campus."
      refreshTimeInSeconds={30}
      localElements={CAPTCHA_ELEMENTS}
    />,
  );
} else {
  console.error(
    "Could not mount because #campus-visit-root was nowhere to be found",
  );
}
